def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    cc = cd = dc = dd = 0
    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
            if b == 'C':
                cc += 1
                opp_c += 1
            else:
                cd += 1
        else:
            if b == 'C':
                dc += 1
                opp_c += 1
            else:
                dd += 1

    my_score = 3 * cc + 5 * dc + dd
    opp_score = 3 * cc + 5 * cd + dd
    opp_d = n - opp_c
    score_diff = my_score - opp_score
    rounds_left = 100 - n

    last_me, last_opp = history[-1]

    recent_len = 10 if n >= 10 else n
    recent_c = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'C':
            recent_c += 1
    recent_opp = recent_c / recent_len if recent_len else 0.5

    # Opponent defection streak
    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break

    # Opponent cooperation streak
    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            coop_streak += 1
        else:
            break

    # Our own defection streak and whether we've been punished
    my_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_def_streak += 1
        else:
            break

    # Strong exploiter detection: high cooperation from us, almost none from them
    if n >= 15 and dc >= 5 and cc <= 2 and opp_c * 4 < n:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # If opponent defects almost always, defect hard but throw in a rare test
    if opp_d * 10 >= n * 9:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Endgame exploitation
    if rounds_left <= 4:
        if recent_opp >= 0.5:
            return 'D'
        if coop_streak >= 1:
            return 'D'
        if def_streak >= 2:
            return 'D'
        return 'C'

    if rounds_left <= 10:
        if recent_opp >= 0.7:
            # squeeze last value but keep cooperation alive until the very end
            if rounds_left <= 2:
                return 'D'
            return 'C'
        if recent_opp <= 0.35:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Against persistent defection, never be a pure sucker
    if def_streak >= 4:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Long mutual cooperation: exploit very rarely, mostly stay cooperative
    if coop_streak >= 8 and my_def_streak == 0:
        if rounds_left > 20 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Respond to opponent's last move
    if last_opp == 'D':
        # Occasional forgiveness to break DD cycles and recover cooperation
        if def_streak == 1 and recent_opp >= 0.6:
            return 'C'
        if def_streak == 1 and rng.random() < 0.35 and rounds_left > 15:
            return 'C'
        if def_streak == 2 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_opp == 'C':
        # If we defected last round and they still cooperated, return to C
        if last_me == 'D':
            if recent_opp >= 0.4:
                return 'C'
            # If they're a pushover, keep exploiting sometimes
            if opp_d <= 2 and rounds_left > 5:
                if rng.random() < 0.25:
                    return 'D'
                return 'C'
            return 'C'

        # Mostly cooperate; occasionally probe a very cooperative opponent
        if recent_opp >= 0.8 and rounds_left > 25:
            if rng.random() < 0.05:
                return 'D'
            return 'C'

        if score_diff < -8 and recent_opp < 0.6:
            if rng.random() < 0.35:
                return 'D'
            return 'C'

        return 'C'

    return 'C'
